const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;min-height:0;min-width:0;padding:10px;color:var(--ink);font:13px/1.45 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden}\n.card *{box-sizing:border-box}\n.home,.scr{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n\n.hd{display:flex;align-items:center;gap:6px;min-width:0;flex:none}\n.hd h1{flex:1 1 0;min-width:0;margin:0;font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sum{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}\n\n.btn{display:inline-flex;align-items:center;justify-content:center;height:28px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font:inherit;font-size:12px;line-height:1;white-space:nowrap;cursor:pointer;flex:none}\n.btn:hover{border-color:var(--accent)}\n.btn:focus-visible,.tab:focus-visible,.ent:focus-visible,.in:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.btn[disabled]{opacity:.55;cursor:default}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.danger{background:var(--ink);color:var(--paper);border-color:transparent;font-weight:600}\n.btn.ghost{background:transparent;color:var(--muted)}\n.btn.sm{height:28px;padding:0 8px}\n\n.tabs{display:flex;border:1px solid var(--line);border-radius:9px;overflow:hidden;flex:none;min-width:0}\n.tab{display:flex;align-items:center;justify-content:center;gap:4px;height:28px;padding:0 10px;border:0;background:transparent;color:var(--muted);font:inherit;font-size:12px;cursor:pointer;white-space:nowrap}\n.tab.on{background:var(--accent);color:var(--on-accent);font-weight:600}\n.cnt{font-size:11px;opacity:.9}\n\n.err{flex:none;padding:5px 8px;border:1px solid var(--accent-alt);border-radius:8px;background:var(--soft);color:var(--ink);font-size:12px;overflow-wrap:anywhere}\n\n.tag{font-size:11px;line-height:1.5;padding:0 7px;border-radius:99px;border:1px solid var(--line);color:var(--muted);white-space:nowrap;flex:none}\n.tag.due{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.tag.off{border-style:dashed}\n.bd{font-size:11px;line-height:1.5;padding:0 6px;border-radius:6px;background:var(--soft);color:var(--ink);white-space:nowrap;flex:none}\n.bd.new{background:var(--accent);color:var(--on-accent);font-weight:600}\n.bd.none{color:var(--muted)}\n.bd.base{border:1px dashed var(--line)}\n.bd.hit{border:1px solid var(--accent);background:transparent}\n\n.one{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column}\n.one>*{flex:1;min-height:0}\n.blockwrap{min-height:0;display:flex;flex-direction:column;gap:6px}\n.list{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.list>*{flex:none}\n.fbar{display:flex;flex-wrap:wrap;gap:6px;flex:none}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip{height:28px;padding:0 10px;border-radius:99px;max-width:100%;overflow:hidden;text-overflow:ellipsis}\n.chip.on{background:var(--soft);border-color:var(--accent);font-weight:600}\n.chip.on::before{content:\"\u2713 \"}\n\n.empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;padding:8px;color:var(--muted);font-size:12px;overflow:auto;min-height:0}\n.empty b{color:var(--ink);font-size:13px}\n\n.ent{display:flex;flex-direction:column;gap:3px;width:100%;min-width:0;text-align:left;padding:6px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink);font:inherit;cursor:pointer}\n.ent.chg{border-left:3px solid var(--accent)}\n.ent:hover{border-color:var(--accent)}\n.l1{display:flex;align-items:baseline;justify-content:space-between;gap:6px;min-width:0}\n.l1 time{font-size:11px;color:var(--muted);white-space:nowrap;flex:none}\n.nm{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600}\n.l2{display:flex;flex-wrap:wrap;gap:4px;min-width:0}\n.l3{display:block;font-size:12px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}\n.l3.nope{display:none}\n\n.src{display:flex;flex-direction:column;gap:4px;min-width:0;padding:7px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.src.off{border-style:dashed}\n.sh1{display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0}\n.meta{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}\n.acts{display:flex;gap:6px;min-width:0}\n.acts.wrap{flex-wrap:wrap}\n\n.sh{margin:0;font-size:12px;font-weight:600;color:var(--muted);flex:none}\n.two{flex:1;min-height:0;display:flex;flex-direction:column;gap:8px}\n.sec{min-height:0;min-width:0;display:flex;flex-direction:column;gap:5px}\n.srcsec{flex:0 1 42%}\n.feedsec{flex:1 1 0}\n.feedsec .blockwrap{flex:1}\n\n.scr-hd{display:flex;align-items:center;gap:8px;min-width:0;flex:none}\n.scr-hd h2{flex:1;min-width:0;margin:0;font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.scr-body{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.scr-body>*{flex:none}\n.scr-ft{display:flex;gap:6px;flex:none}\n.scr-ft .btn{flex:1;height:32px}\n.scr-ft .btn.primary{flex:2}\n\n.big{font-size:16px;font-weight:700;overflow-wrap:anywhere}\n.note{margin:0;font-size:12px;color:var(--muted);overflow-wrap:anywhere}\n.kv{display:flex;gap:8px;font-size:12px;min-width:0}\n.lab{color:var(--muted);font-size:12px;flex:none;min-width:5em}\n.val{min-width:0;flex:1;overflow-wrap:anywhere;word-break:break-word}\n.lnk{color:var(--accent);text-decoration:underline;overflow-wrap:anywhere;word-break:break-all}\n\n.blk h4{margin:0 0 4px;font-size:12px}\n.ln{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:4px}\n.ln li{display:flex;gap:6px;align-items:flex-start;padding:5px 7px;border-radius:8px;background:var(--soft);font-size:12px;min-width:0}\n.sg{font-weight:700;flex:none}\n.tx{min-width:0;flex:1;overflow-wrap:anywhere}\n\n.notice{display:flex;flex-direction:column;gap:2px;padding:7px 9px;border:1px dashed var(--accent-alt);border-radius:8px;background:var(--soft);font-size:12px}\n.confirm{display:flex;flex-direction:column;gap:6px;padding:8px;border:1px solid var(--accent-alt);border-radius:8px;font-size:12px;overflow-wrap:anywhere}\n\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.in{width:100%;min-width:0;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:13px}\n.ta{resize:vertical;min-height:52px}\n.ta.big{min-height:110px;font-size:13px;font-weight:400}\n.hint{font-size:11px;color:var(--muted)}\n\n/* 194x194\uff1a\u53ea\u7559\u6807\u7b7e\u9875 + \u6dfb\u52a0\uff0c\u8be6\u60c5\u7528\u6574\u5c4f */\n.card[data-size=\"3x3\"]{padding:8px}\n.card[data-size=\"3x3\"] .home,.card[data-size=\"3x3\"] .scr{gap:5px}\n.card[data-size=\"3x3\"] .tabs{flex:1}\n.card[data-size=\"3x3\"] .tab{flex:1;padding:0 4px}\n.card[data-size=\"3x3\"] .add{width:30px;padding:0}\n.card[data-size=\"3x3\"] .l3{display:none}\n.card[data-size=\"3x3\"] .chip.only:not(.on){display:none}\n.card[data-size=\"3x3\"] .ent{padding:5px 7px;gap:2px}\n.card[data-size=\"3x3\"] .big{font-size:14px}\n.card[data-size=\"3x3\"] .ta.big{min-height:80px}\n\n/* \u7a84\u957f\u5361\uff1a\u6807\u9898 + \u6dfb\u52a0\u4e00\u884c\uff0c\u6807\u7b7e\u9875\u53e6\u8d77\u4e00\u884c */\n.card[data-size=\"3x6\"] .hd{flex-wrap:wrap}\n.card[data-size=\"3x6\"] .tabs{flex:1 0 100%;order:3}\n.card[data-size=\"3x6\"] .tab{flex:1}\n.card[data-size=\"3x3\"] .kv,.card[data-size=\"3x6\"] .kv{flex-direction:column;gap:0}\n\n/* \u5bbd\u6241\u5361\uff1a\u6807\u9898\u3001\u6807\u7b7e\u9875\u3001\u6dfb\u52a0\u540c\u4e00\u884c\uff0c\u6765\u6e90\u884c\u5de6\u53f3\u5206\u680f */\n.card[data-size=\"6x3\"] .tab{padding:0 12px}\n.card[data-size=\"6x3\"] .src,.card[data-size=\"6x6\"] .src{display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:10px;row-gap:2px;align-items:center}\n.card[data-size=\"6x3\"] .sh1,.card[data-size=\"6x6\"] .sh1{justify-content:flex-start}\n.card[data-size=\"6x3\"] .meta,.card[data-size=\"6x6\"] .meta{grid-column:1}\n.card[data-size=\"6x3\"] .acts,.card[data-size=\"6x6\"] .acts{grid-column:2;grid-row:1 / span 2}\n\n.card[data-size=\"6x6\"]{padding:12px;gap:8px}\n.card[data-size=\"6x6\"] .scr-body{gap:10px}\n.card[data-size=\"6x6\"] .ta.big{min-height:150px}\n";
var FREQS=[
  {v:'hourly',l:'每小时',ms:3600000},
  {v:'daily',l:'每天',ms:86400000},
  {v:'weekly',l:'每周',ms:604800000},
  {v:'monthly',l:'每月',ms:2592000000}
];
var NOTICE='平台目前没有网页抓取、AI 总结和定时任务接口，卡片没法自己打开官网。请先打开官网，把更新日志或公告里的文字粘贴到下面；卡片会逐行和上次保存的内容对比，列出新增和删除，并留下这次记录。';
var FREQ_HINT='频率只用来标出“该检查了”。目前没有后台定时任务，不会自动抓取，需要你点「立即检查」。';

function freqOf(v){for(var i=0;i<FREQS.length;i++)if(FREQS[i].v===v)return FREQS[i];return FREQS[1];}
function p2(n){return n<10?'0'+n:''+n;}
function fmtTime(ts){
  var d=new Date(ts),n=new Date();
  var s=p2(d.getMonth()+1)+'-'+p2(d.getDate())+' '+p2(d.getHours())+':'+p2(d.getMinutes());
  return d.getFullYear()===n.getFullYear()?s:d.getFullYear()+'-'+s;
}
function fmtSpan(ms){
  var m=Math.round(ms/60000);
  if(m<60)return Math.max(m,1)+' 分钟';
  var h=Math.round(m/60);
  if(h<48)return h+' 小时';
  return Math.round(h/24)+' 天';
}
function hostOf(u){var m=/^https?:\/\/([^\/?#]+)/i.exec(String(u||''));return m?m[1].replace(/^www\./,''):String(u||'');}
function validUrl(u){return /^https?:\/\/[^\s\/?#]+[^\s]*$/i.test(String(u||''));}

function norm(s){
  return {
    sources:Array.isArray(s&&s.sources)?s.sources:[],
    logs:Array.isArray(s&&s.logs)?s.logs:[]
  };
}
function lastLog(logs,sid){
  var best=null;
  for(var i=0;i<logs.length;i++){
    if(logs[i].sourceId===sid&&(!best||logs[i].at>best.at))best=logs[i];
  }
  return best;
}
function splitLines(text){
  var out=[],a=String(text||'').split(/\r?\n/);
  for(var i=0;i<a.length;i++){
    var t=a[i].replace(/\s+/g,' ').trim();
    if(t)out.push(t.length>400?t.slice(0,400)+'…':t);
  }
  return out;
}
function keywords(focus){
  var a=String(focus||'').toLowerCase().split(/[,，、;；\s]+/),out=[];
  for(var i=0;i<a.length;i++)if(a[i])out.push(a[i]);
  return out;
}
function markLines(arr,kws){
  return arr.map(function(t){
    var lo=t.toLowerCase(),hit=false;
    for(var i=0;i<kws.length;i++)if(lo.indexOf(kws[i])>=0){hit=true;break;}
    return {t:t,hit:hit};
  });
}
function diffLines(a,b){
  var ca={},cb={},ua={},ub={},add=[],del=[],i,k;
  for(i=0;i<a.length;i++){k='k'+a[i];ca[k]=(ca[k]||0)+1;}
  for(i=0;i<b.length;i++){k='k'+b[i];cb[k]=(cb[k]||0)+1;}
  for(i=0;i<b.length;i++){k='k'+b[i];ub[k]=(ub[k]||0)+1;if(ub[k]>(ca[k]||0))add.push(b[i]);}
  for(i=0;i<a.length;i++){k='k'+a[i];ua[k]=(ua[k]||0)+1;if(ua[k]>(cb[k]||0))del.push(a[i]);}
  return {added:add,removed:del};
}
function chg(l){return !l.first&&((l.added&&l.added.length)||(l.removed&&l.removed.length))?true:false;}
function sumText(l){
  if(l.first)return '首次记录（基线）';
  var a=l.added?l.added.length:0,r=l.removed?l.removed.length:0,p=[];
  if(!a&&!r)return '无变化';
  if(a)p.push('新增 '+a);
  if(r)p.push('删除 '+r);
  return p.join(' · ');
}


function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid}=ctx;
  const size=ctx.size||'3x3';
  const S=norm(state);
  const T=Date.now();
  if(!ui.tab)ui.tab='feed';

  function A(...a){return a.filter(function(x){return x!==null&&x!==undefined&&x!==false;});}
  function btn(label,fn,cls,attrs){
    return el('button',Object.assign({type:'button',class:'btn'+(cls?' '+cls:''),onclick:fn},attrs||{}),label);
  }
  function go(p){Object.assign(ui,p);redraw();}
  function fail(){ui.err='保存失败，已保留原数据，请重试';ui.busy=false;ui.formErr=null;redraw();}
  function srcOf(id){for(var i=0;i<S.sources.length;i++)if(S.sources[i].id===id)return S.sources[i];return null;}
  function link(u){return el('a',{class:'lnk',href:u,target:'_blank',rel:'noopener noreferrer'},u);}
  function errBox(m){return m?el('div',{class:'err',role:'alert'},'⚠ '+m):null;}
  function dueOf(s){
    if(s.paused)return {t:'已暂停',c:'off'};
    const l=lastLog(S.logs,s.id);
    if(!l)return {t:'待首次记录',c:'due'};
    const nx=l.at+freqOf(s.freq).ms;
    return nx<=T?{t:'该检查了',c:'due'}:{t:fmtSpan(nx-T)+'后检查',c:'ok'};
  }
  function openEdit(s){
    go({draft:s?{name:s.name,url:s.url,focus:s.focus||'',freq:s.freq||'daily'}:{name:'',url:'',focus:'',freq:'daily'},formErr:null,busy:false,screen:{name:'edit',id:s?s.id:null}});
  }
  function openCheck(s){
    go({draft:{refUrl:s.url,content:''},formErr:null,busy:false,screen:{name:'check',id:s.id}});
  }
  function togglePause(s){
    ui.err=null;
    update(function(cur){
      const n=norm(cur);
      return Object.assign({},cur,{
        sources:n.sources.map(function(x){return x.id===s.id?Object.assign({},x,{paused:!x.paused}):x;}),
        logs:n.logs
      });
    }).catch(fail);
  }

  function tabBtn(k,label,n){
    return el('button',{type:'button',class:'tab'+(ui.tab===k?' on':''),'aria-pressed':ui.tab===k?'true':'false',onclick:function(){go({tab:k});}},
      label,el('span',{class:'cnt'},String(n)));
  }
  function emptyBox(title,text,action){
    return el('div',{class:'empty'},...A(el('b',{},title),el('span',{},text),action));
  }

  function logRow(l){
    const c=chg(l);
    const pick=(l.added||[]).find(function(x){return x.hit;})||(l.added||[])[0]||(l.removed||[])[0];
    const isAdd=pick&&(l.added||[]).indexOf(pick)>=0;
    return el('button',{type:'button',class:'ent'+(c?' chg':''),onclick:function(){go({screen:{name:'log',id:l.id}});}},
      el('span',{class:'l1'},el('b',{class:'nm'},l.name),el('time',{},fmtTime(l.at))),
      el('span',{class:'l2'},...A(
        el('span',{class:'bd '+(l.first?'base':c?'new':'none')},sumText(l)),
        l.hits?el('span',{class:'bd hit'},'命中关注 '+l.hits):null)),
      pick&&!l.first?el('span',{class:'l3'},(isAdd?'＋ ':'－ ')+pick.t):el('span',{class:'l3 nope'}));
  }

  function feedBlock(){
    let logs=S.logs.slice().sort(function(a,b){return b.at-a.at;});
    if(ui.fSrc)logs=logs.filter(function(l){return l.sourceId===ui.fSrc;});
    if(ui.onlyChg)logs=logs.filter(chg);
    let fname='';
    if(ui.fSrc){const s=srcOf(ui.fSrc);const f=S.logs.find(function(l){return l.sourceId===ui.fSrc;});fname=s?s.name:(f?f.name:'该来源');}
    const bar=S.logs.length?el('div',{class:'fbar'},...A(
      btn('只看有变化',function(){go({onlyChg:!ui.onlyChg});},'chip only'+(ui.onlyChg?' on':''),{'aria-pressed':ui.onlyChg?'true':'false'}),
      ui.fSrc?btn(fname+' ✕',function(){go({fSrc:null});},'chip on',{'aria-label':'取消按来源筛选'}):null)):null;
    let list;
    if(!S.sources.length&&!S.logs.length){
      list=emptyBox('还没有来源','先添加要跟踪的官网链接，再点「立即检查」留下第一条记录。',btn('添加来源',function(){openEdit(null);},'primary'));
    }else if(!S.logs.length){
      list=emptyBox('还没有检查记录','到「来源」里点「立即检查」，贴入官网更新内容，这里会列出和上次相比的变化。',btn('去检查',function(){go({tab:'src'});},'primary'));
    }else if(!logs.length){
      list=emptyBox('没有符合条件的记录','换个筛选看看。',btn('清除筛选',function(){go({fSrc:null,onlyChg:false});}));
    }else{
      list=el('div',{class:'list'},...logs.map(logRow));
    }
    return el('div',{class:'blockwrap'},...A(bar,list));
  }

  function srcRow(s){
    const d=dueOf(s),last=lastLog(S.logs,s.id);
    return el('div',{class:'src'+(s.paused?' off':'')},
      el('div',{class:'sh1'},el('b',{class:'nm'},s.name),el('span',{class:'tag '+d.c},d.t)),
      el('div',{class:'meta'},hostOf(s.url)+' · '+freqOf(s.freq).l+' · '+(last?'上次 '+fmtTime(last.at):'未记录')),
      el('div',{class:'acts'},
        btn('立即检查',function(){openCheck(s);},'primary sm'),
        btn(s.paused?'恢复':'暂停',function(){togglePause(s);},'sm'),
        btn('详情',function(){go({screen:{name:'src',id:s.id},confirmDel:null});},'sm')));
  }
  function srcList(){
    if(!S.sources.length){
      return emptyBox('还没有要跟踪的官网','填入官网链接、你关心的内容和检查频率，就能开始记录每次的变化。',btn('添加来源',function(){openEdit(null);},'primary'));
    }
    return el('div',{class:'list'},...S.sources.map(srcRow));
  }

  function home(){
    const dueN=S.sources.filter(function(s){return dueOf(s).c==='due';}).length;
    const wide=size==='6x6';
    const add=btn(size==='3x3'?'＋':'＋ 添加来源',function(){openEdit(null);},'primary add',{'aria-label':'添加来源'});
    const hd=el('div',{class:'hd'},...A(
      size!=='3x3'?el('h1',{},'产品更新跟踪'):null,
      wide?el('span',{class:'sum'},S.sources.length+' 个来源'+(dueN?' · '+dueN+' 个该检查':'')):
        el('div',{class:'tabs'},tabBtn('feed','更新',S.logs.length),tabBtn('src','来源',S.sources.length)),
      add));
    const body=wide?
      el('div',{class:'two'},
